// CSV of the ACTIVE tab (plain-text mirror of the table columns).
const nlCsv = () => {
    if (!_nlLast) return;
    const d = _nlLast;
    const esc = (v) => { const s = String(v ?? ''); return /[",\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s; };
    let headers = []; let rows = [];
    if (_nlTab === 'referral') {
        headers = ['Board', 'Name', 'Head Count', 'Converted', 'Last Referral'];
        rows = [...d.referral.agents.map(r => ['Agent', r.name, r.count, r.converted, r.last]),
                ...d.referral.clients.map(r => ['Client (' + (r.type === 'c' ? 'customer' : 'prospect') + ')', r.name, r.count, r.converted, r.last])];
    } else if (_nlTab === 'coverage') {
        headers = ['Group', 'Name', 'Tag', 'Meet', 'Class', 'CPS', 'Call', 'WA', 'Total', 'Last Touch', 'Days Since', 'Agent'];
        rows = [...d.coverage.custMet.map(r => ['Customer contacted', r.name, r.tag, r.meet, r.cls, r.cps, r.call, r.wa, _nlFmtW(r.w), r.last, '', r.agentName]),
                ...d.coverage.custNotMet.map(r => ['NOT contacted 90d', r.name, '', 0, 0, 0, 0, 0, 0, r.last || '', r.days === null ? '365+' : r.days, r.agentName]),
                ...d.coverage.prospMet.map(r => ['Prospect met', r.name, r.hot ? 'Hot' : r.firstMet ? 'First met' : 'Ongoing', r.meet, r.cls, r.cps, r.call, r.wa, _nlFmtW(r.w), r.last, '', r.agentName])];
    } else if (_nlTab === 'audited') {
        headers = ['Customer', 'Type of Audit Service', 'Audit Date', 'Agent'];
        rows = d.audited.map(r => [r.name, r.services, r.date, r.agentName]);
    } else {
        headers = ['Name', 'P/C', 'Category', 'Mentions', 'Tick', 'Event', 'Talk', 'Profile', 'Last Mention', 'Grade', 'Agent'];
        rows = (d.topics[_nlTab] || []).map(r => [r.name, r.type === 'c' ? 'Customer' : 'Prospect', r.cat, r.total, r.tick, r.event, r.talk, r.profile ? 'yes' : '', r.last, r.grade, r.agentName]);
    }
    // Excel needs a UTF-8 BOM prefix or Chinese names open as mojibake.
    const csv = String.fromCharCode(0xFEFF) + [headers, ...rows].map(line => line.map(esc).join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = `name-list-${_nlTab}-${toLocalDateStr(new Date())}.csv`;
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(a.href), 5000);
};

const getActivityHeadcount = async (from, to) => {
    const activities = await _reportActsInRange(from, to, 'getActivityHeadcount');
    const [attendees, prospects, customers] = await Promise.all([
        AppDataStore.getAll('event_attendees'),
        _visibleUserIds !== 'all' ? AppDataStore.getAll('prospects') : Promise.resolve([]),
        _visibleUserIds !== 'all' ? AppDataStore.getAll('customers') : Promise.resolve([])
    ]);
    const actMap = {};
    activities.forEach(a => { actMap[a.id] = a; });
    const prospMap = {};
    prospects.forEach(p => { prospMap[p.id] = p; });
    const custMap = {};
    customers.forEach(c => { custMap[c.id] = c; });
    let count = 0;
    for (const att of attendees) {
        if (!att.attended && att.attendance_status !== 'Attended') continue;
        const act = actMap[att.activity_id];
        const date = act?.activity_date || '';
        if (date < from || date > to) continue;
        if (!_recInMarket(act || {})) continue;
        if (_visibleUserIds !== 'all') {
            const entityId = att.entity_id || att.attendee_id;
            let agentId;
            if (att.attendee_type === 'agent') {
                agentId = entityId;
            } else if (att.attendee_type === 'customer') {
                agentId = custMap[entityId]?.responsible_agent_id;
            } else {
                agentId = prospMap[entityId]?.responsible_agent_id;
            }
            if (!_visibleUserIds.includes(agentId)) continue;
        }
        count++;
    }
    return count;
};

// ── Pitching head-counts (Post-Meetup Notes → Potential & Opportunities) ─────
// Two person-deduped head-counts sourced from the activity's
// `opportunity_potential` field — the serialized checkbox-list the Post-Meetup
// Notes "Potential & Opportunities" block writes (buildPostMeetupNotesBlock /
// serializeMultiSelectToText). Format is `[Products] A, B | [Bujishu] C |
// Remarks: …`. We parse ONLY the group-marked selected items (never the free
// Remarks text) so a remark that happens to contain "专案"/"灵活" can't inflate
// the count. parseSelectedItems lives in the calendar chunk (may be unloaded
// when reporting runs), so its logic is re-declared here — same pattern as
// _wrParseEventCategories above.
const _parseOppSelected = (raw) => {
    if (!raw) return [];
    const remarksMatch = raw.match(/\|\s*Remarks:\s*([\s\S]*)/);
    const itemsPart = remarksMatch ? raw.slice(0, remarksMatch.index) : raw;
    const selected = [];
    const groupRegex = /\[([^\]]+)\]\s*([^[|]*)/g;
    let m;
    while ((m = groupRegex.exec(itemsPart)) !== null) {
        m[2].split(',').map(n => n.trim()).filter(Boolean).forEach(n => selected.push(n));
    }
    return selected;
};

// Collapse the prospect/customer dual record to ONE person key. Activities are
// normally FK'd to a prospect, but a pitch logged against an existing customer
// carries only customer_id; that customer links back to its originating prospect
// via converted_from_prospect_id, so the same human dedups to the same prospect
// key whether met as a prospect or as a converted customer. custToProspect maps
// String(customer_id) → prospect_id.
const _buildCustToProspect = (customers) => {
    const m = new Map();
    (customers || []).forEach(c => {
        if (c.converted_from_prospect_id != null) m.set(String(c.id), c.converted_from_prospect_id);
    });
    return m;
};
const _pitchPersonKey = (a, custToProspect) => {
    if (a.prospect_id) return 'p' + a.prospect_id;
    if (a.customer_id) {
        const p = custToProspect.get(String(a.customer_id));
        return p != null ? 'p' + p : 'c' + a.customer_id;
    }
    return 'a' + a.id;
};

// Count DISTINCT persons (resolved to prospect via _pitchPersonKey) with at least
// one in-range activity whose Potential & Opportunities selection matches
// `predicate`. Repeat meetings — and prospect vs converted-customer records of the
// same person — collapse to 1 (the Set). Same scope contract as
// getActivityTypeCount: date window, _visibleUserIds (lead_agent_id),
// _currentRoleFilter, and _recInMarket market drill-down.
const _pitchHeadcount = async (from, to, predicate, ctx) => {
    const needUsers = _currentRoleFilter !== 'All';
    const [activities, customers] = await Promise.all([
        _reportActsInRange(from, to, ctx),
        AppDataStore.getAll('customers'),
    ]);
    const users = needUsers ? await AppDataStore.getAll('users') : [];
    const userMap = {};
    users.forEach(u => { userMap[u.id] = u; });
    const custToProspect = _buildCustToProspect(customers);
    const seen = new Set();
    for (const a of activities) {
        if (a.activity_date < from || a.activity_date > to) continue;
        if (!_recInMarket(a)) continue;
        if (_visibleUserIds !== 'all' && !_visibleUserIds.includes(a.lead_agent_id)) continue;
        if (_currentRoleFilter !== 'All') {
            const agent = userMap[a.lead_agent_id];
            if (!agent || agent.role !== _currentRoleFilter) continue;
        }
        if (!_parseOppSelected(a.opportunity_potential || '').some(predicate)) continue;
        seen.add(_pitchPersonKey(a, custToProspect));
    }
    return seen.size;
};

// NEA Pitching: person ticked "DC 代理配套" (Agent Package) in P&O.
const getNeaPitchingHeadcount = (from, to) =>
    _pitchHeadcount(from, to, s => s.includes('代理配套'), 'getNeaPitchingHeadcount');

// Fengshui Pitching: person ticked 灵活 (flexi audit) OR 专案 (project audit) in
// P&O. Deduped per person → ticking both still counts as 1.
const getFengshuiPitchingHeadcount = (from, to) =>
    _pitchHeadcount(from, to, s => s.includes('灵活') || s.includes('专案'), 'getFengshuiPitchingHeadcount');

// ── Weekly-report auto-fill getters ────────────────────────────────────────
// Two scope-correct, date-windowed counters cloned from the proven KPI getters
// above, used ONLY by _wrAutoFill. Each mirrors getCPSCount's exact scope+date
// contract (so a wrong/over-broad number can never reach the boss report).

// Count activities of a single activity_type in [from,to] — direct clone of
// getCPSCount, with the literal 'CPS' generalised to a `type` argument. Same
// _visibleUserIds (lead_agent_id) + _currentRoleFilter scoping; same inclusive
// date window on activity_date.
const getActivityTypeCount = async (from, to, type) => {
    const needUsers = _currentRoleFilter !== 'All' || _visibleUserIds !== 'all';
    const activities = await _reportActsInRange(from, to, 'getActivityTypeCount:' + type);
    const users = needUsers ? await AppDataStore.getAll('users') : [];
    const userMap = {};
    users.forEach(u => { userMap[u.id] = u; });
    let count = 0;
    for (const a of activities) {
        if (a.activity_type !== type || a.activity_date < from || a.activity_date > to) continue;
        if (!_recInMarket(a)) continue;
        if (_visibleUserIds !== 'all' && !_visibleUserIds.includes(a.lead_agent_id)) continue;
        if (_currentRoleFilter !== 'All') {
            const agent = userMap[a.lead_agent_id];
            if (!agent || agent.role !== _currentRoleFilter) continue;
        }
        count++;
    }
    return count;
};

// Parse a stored event `categories` value (JSON-string array, real array, or a
// comma-joined fallback) into a string[]. Mirror of parseEventCategories in
// script-activities.js / script-marketing.js (that helper is local to those
// chunks, so it's re-declared here rather than imported).
const _wrParseEventCategories = (raw) => {
    if (!raw) return [];
    if (Array.isArray(raw)) return raw;
    try {
        const parsed = JSON.parse(raw);
        return Array.isArray(parsed) ? parsed : [];
    } catch (_) {
        return String(raw).split(',').map(s => s.trim()).filter(Boolean);
    }
};

// Attended-headcount of events whose `categories` array intersects categoryList,
// with the registration's event_date in [from,to]. Reuses the SAME table + filter
// the live "Headcount by Event Type" dashboard card uses (getHeadcountByEventType):
//   table  = event_registrations  (the mirror written on attendance toggle)
//   filter = attendance_status === 'Attended'
//   date   = r.event_date (inclusive)
// joined to events by event_id to read `categories`. Optional attendeeTypes
// (e.g. ['customer']) restricts which attendee rows count; default counts any
// attendee. Scoping: resolves each attendee's responsible agent (agent rows by
// entity, customer/prospect rows via responsible_agent_id) and keeps it only if
// in _visibleUserIds — same resolution as getActivityHeadcount. When scope is
// 'all' no per-row resolution is needed (matches the dashboard card's behaviour).
const getEventCategoryHeadcount = async (from, to, categoryList, attendeeTypes) => {
    const wanted = new Set(categoryList || []);
    const typeFilter = (attendeeTypes && attendeeTypes.length) ? new Set(attendeeTypes) : null;
    const scoped = _visibleUserIds !== 'all';
    const [events, registrations, prospects, customers] = await Promise.all([
        AppDataStore.getAll('events'),
        AppDataStore.getAll('event_registrations'),
        scoped ? AppDataStore.getAll('prospects') : Promise.resolve([]),
        scoped ? AppDataStore.getAll('customers') : Promise.resolve([]),
    ]);
    // Events whose categories intersect the wanted set (RAW id key, parity with
    // getHeadcountByEventType's regsByEvent.get(ev.id)).
    const matchedEventIds = new Set();
    for (const ev of events) {
        if (!_recInMarket(ev)) continue;
        const cats = _wrParseEventCategories(ev.categories);
        if (cats.some(c => wanted.has(c))) matchedEventIds.add(ev.id);
    }
    if (matchedEventIds.size === 0) return 0;
    const prospMap = {}; prospects.forEach(p => { prospMap[p.id] = p; });
    const custMap = {}; customers.forEach(c => { custMap[c.id] = c; });
    let count = 0;
    for (const r of registrations) {
        if (!matchedEventIds.has(r.event_id)) continue;
        if (r.attendance_status !== 'Attended') continue;
        if (r.event_date < from || r.event_date > to) continue;
        if (typeFilter && !typeFilter.has(r.attendee_type)) continue;
        if (scoped) {
            let agentId;
            if (r.attendee_type === 'agent') {
                agentId = r.attendee_id;
            } else if (r.attendee_type === 'customer') {
                agentId = custMap[r.attendee_id] && custMap[r.attendee_id].responsible_agent_id;
            } else {
                agentId = prospMap[r.attendee_id] && prospMap[r.attendee_id].responsible_agent_id;
            }
            if (!_visibleUserIds.includes(agentId)) continue;
        }
        count++;
    }
    return count;
};

// New customer CONVERSIONS in [from,to] — customers whose customer_since falls in
// range, regardless of any purchase. Mirrors the "convertedCount" branch of the
// conversion-rate getter (NOT getNewCustomers, which additionally requires a
// purchase in range). Scoped by responsible_agent_id.
const getConvertedCustomers = async (from, to) => {
    const customers = await AppDataStore.getAll('customers');
    let count = 0;
    for (const c of customers) {
        if (c.customer_since < from || c.customer_since > to) continue;
        if (!_recInMarket(c)) continue;
        if (_visibleUserIds !== 'all' && !_visibleUserIds.includes(c.responsible_agent_id)) continue;
        count++;
    }
    return count;
};

// ========== KPI DRILL-DOWN: detail builders ==========
const renderDetailTable = (headers, rows, emptyMsg = 'No records in this period') => {
    if (!rows.length) return `<div style="padding:32px;text-align:center;color:var(--gray-400);">${emptyMsg}</div>`;
    return `
        <div style="max-height:55vh;overflow:auto;border:1px solid var(--border,#e5e0d8);border-radius:6px;">
            <table style="width:100%;border-collapse:collapse;font-size:13px;">
                <thead style="background:var(--gray-50,#f7f4ed);position:sticky;top:0;z-index:1;">
                    <tr>${headers.map(h => `<th scope="col" style="padding:10px 12px;text-align:left;font-weight:600;color:var(--gray-500);border-bottom:1px solid var(--border,#e5e0d8);">${h}</th>`).join('')}</tr>
                </thead>
                <tbody>
                    ${rows.map(r => `<tr>${r.map(cell => `<td style="padding:10px 12px;border-bottom:1px solid var(--gray-100,#f1ede3);">${escapeHtml(cell ?? '—')}</td>`).join('')}</tr>`).join('')}
                </tbody>
            </table>
        </div>
        <div style="text-align:right;margin-top:8px;font-size:12px;color:var(--gray-400);">${rows.length} record${rows.length === 1 ? '' : 's'}</div>
    `;
};

// Shared fast path for the three purchase drill-downs (total sales / POP / EPP):
// returns only the period+scope+role purchase rows (agent + customer names
// joined server-side) via the report_purchase_details RPC, instead of
// getAll('purchases') + getAll('customers') per click. Each builder sub-filters
// (NOT is_agent_package / payment_method) and formats. Returns null on any
// error → the builder's original getAll path runs. Behavior-preserving,
// including null-date rows (see the RPC's NULL-date parity note).
const _tryPurchaseDetails = async (from, to) => {
    if (!window.supabase || !window.supabase.rpc) return null;
    // Market drill-down: report_purchase_details isn't country/currency-aware, so a
    // scoped market would leak all-markets rows into the breakdown (contradicting the
    // market-scoped card). Fall back to the client path, which filters by market.
    if (window._crmUtils.listCountryScope() !== window._crmUtils.ALL_COUNTRIES) return null;
    try {
        const agentIds = (_visibleUserIds === 'all' || !Array.isArray(_visibleUserIds))
            ? null
            : _visibleUserIds.map(v => Number(v)).filter(n => Number.isFinite(n));
        const role = (!_currentRoleFilter || _currentRoleFilter === 'All') ? null : _currentRoleFilter;
        const { data, error } = await window.supabase.rpc('report_purchase_details', {
            p_from: from, p_to: to, p_agent_ids: agentIds, p_role: role
        });
        if (error || !Array.isArray(data)) return null;
        return data;
    } catch (_) {
        return null;
    }
};

// Shared fast path for the activity drill-downs (CPS / meetings / client
// meetings / meet-up / CF headcount): returns only the period+scope+role
// activity rows matching a type set (and/or a title pattern), with agent +
// entity names joined, via report_activity_details. Returns null on error →
// the builder's original getAll path runs. Behavior-preserving.
const _tryActivityDetails = async (from, to, types, titleLike = null) => {
    if (!window.supabase || !window.supabase.rpc) return null;
    // Market drill-down: report_activity_details isn't country-aware, so fall back to
    // the client path (which applies _recInMarket) when a specific market is active.
    if (window._crmUtils.listCountryScope() !== window._crmUtils.ALL_COUNTRIES) return null;
    try {
        const agentIds = (_visibleUserIds === 'all' || !Array.isArray(_visibleUserIds))
            ? null
            : _visibleUserIds.map(v => Number(v)).filter(n => Number.isFinite(n));
        const role = (!_currentRoleFilter || _currentRoleFilter === 'All') ? null : _currentRoleFilter;
        const { data, error } = await window.supabase.rpc('report_activity_details', {
            p_from: from, p_to: to, p_agent_ids: agentIds, p_role: role,
            p_types: types || null, p_title_like: titleLike
        });
        if (error || !Array.isArray(data)) return null;
        return data;
    } catch (_) {
        return null;
    }
};

const buildCPSDetails = async (from, to) => {
    // Always the client scan. report_activity_details returns neither prospect_id
    // nor the referrer columns (see migrations/report_activity_details_2026-06-14.sql),
    // and the referrer breakdown is the whole point of this drill-down — it is what
    // makes the card's two head-count chips auditable. Same intentional RPC bypass
    // as buildActivityHeadcountDetails.
    return _buildCPSDetailsLegacy(from, to);
};

// ONE scan behind BOTH referrer drill-downs (CPS sessions and CF Headcount), so
// they can never disagree about who referred what. Returns the session rows, the
// per-referrer rollup, and the count of sessions with no referrer recorded.
// Same scope gates as getCPSCount / getCPSReferrerSplit.
const _cpsSessionScan = async (from, to) => {
    // Date-windowed read (was getAll('activities') — a whole-table scan on every
    // drill-down click).
    const activities = await _reportActsInRange(from, to, '_cpsSessionScan');
    const [users, customers, prospects] = await Promise.all([
        AppDataStore.getAll('users'),
        AppDataStore.getAll('customers'),
        AppDataStore.getAll('prospects')
    ]);
    const userMap = {}; users.forEach(u => { userMap[u.id] = u; });
    const custMap = {}; customers.forEach(c => { custMap[c.id] = c; });
    const prospMap = {}; prospects.forEach(p => { prospMap[p.id] = p; });
    const rows = [];
    // key → { name, isAgent, sessions }. Keyed exactly as getCPSReferrerSplit
    // keys its Sets, so the distinct row counts below MUST equal the card chips.
    const byReferrer = new Map();
    for (const a of activities) {
        if (a.activity_type !== 'CPS' || a.activity_date < from || a.activity_date > to) continue;
        if (!_recInMarket(a)) continue;
        if (_visibleUserIds !== 'all' && !_visibleUserIds.includes(a.lead_agent_id)) continue;
        if (_currentRoleFilter !== 'All') {
            const agent = userMap[a.lead_agent_id];
            if (!agent || agent.role !== _currentRoleFilter) continue;
        }
        const agentName = userMap[a.lead_agent_id]?.full_name || 'Unknown';
        const cust = a.customer_id ? custMap[a.customer_id] : null;
        const prosp = a.prospect_id ? prospMap[a.prospect_id] : null;
        const entityName = cust?.full_name || prosp?.full_name || a.customer_name || '—';
        const ref = _cpsReferrerOf(prosp);
        if (ref) {
            const seen = byReferrer.get(ref.key);
            if (seen) seen.sessions++;
            else byReferrer.set(ref.key, { name: ref.name || '—', isAgent: ref.isAgent, sessions: 1 });
        }
        rows.push([
            a.activity_date, agentName, entityName,
            ref ? (ref.name || '—') : '—',
            ref ? (ref.isAgent ? 'Agent' : 'Client') : 'Not recorded',
            a.activity_title || 'CPS Session'
        ]);
    }

    const referrers = [...byReferrer.values()].sort((x, y) => y.sessions - x.sessions);
    const unattributed = rows.filter(r => r[4] === 'Not recorded').length;
    return { rows, referrers, unattributed };
};

// CPS drill-down: every session + who referred it, plus the by-referrer rollup
// that makes the card's two chips auditable.
const _buildCPSDetailsLegacy = async (from, to) => {
    const [{ rows, referrers, unattributed }, win] = await Promise.all([
        _cpsSessionScan(from, to),
        // Rolling-window roster for the momentum section below. Promise-cached and
        // already computed for the card, so this costs nothing on a normal click.
        // Never let it break the drill-down — the period tables are the main event.
        getCPSReferrerWindows().catch(e => { console.warn('[reports] CPS windows unavailable:', e && e.message); return null; }),
    ]);
    const agentHeads = referrers.filter(r => r.isAgent).length;
    const clientHeads = referrers.length - agentHeads;

    const summary = `<div style="background:#f0f9ff;border:1px solid #bae6fd;border-radius:6px;padding:10px 14px;margin-bottom:12px;font-size:13px;">
        <strong>${rows.length}</strong> CPS session${rows.length === 1 ? '' : 's'}
        &nbsp;·&nbsp; <strong>${agentHeads}</strong> agent referrer${agentHeads === 1 ? '' : 's'}
        &nbsp;·&nbsp; <strong>${clientHeads}</strong> client referrer${clientHeads === 1 ? '' : 's'}
        ${unattributed > 0 ? `&nbsp;·&nbsp; <strong>${unattributed}</strong> with no referrer recorded` : ''}
        <div style="margin-top:4px;color:var(--gray-500);font-size:11px;">Referrer counts are distinct people — one referrer who brought several prospects still counts once, so they do not add up to the session total.</div>
    </div>`;

    const byReferrerTable = `<h4 style="font-size:14px;font-weight:600;margin:0 0 8px;">By referrer (${referrers.length})</h4>`
        + renderDetailTable(['Referrer', 'Type', 'CPS Sessions'],
            referrers.map(r => [r.name, r.isAgent ? 'Agent' : 'Client', r.sessions]),
            'No referrers recorded in this period');

    // Who is behind the 90d/365d line on the card — and, more usefully, who ISN'T
    // any more. Rolling windows, so this section does NOT follow the time filter
    // (it does follow agent/role/market, same as the card).
    const windowSection = !win ? '' : (() => {
        const quiet = win.roster.filter(r => !r.recent).length;
        return `<h4 style="font-size:14px;font-weight:600;margin:18px 0 8px;">
                Referrer activity — rolling windows
                <span style="font-weight:400;color:var(--gray-500);font-size:12px;">
                    · 90d ${win.from90} → ${win.to} · 365d from ${win.from365}
                </span>
            </h4>
            <div style="font-size:12px;color:var(--gray-500);margin-bottom:8px;">
                👤 <strong>${win.agents90}/${win.agents365}</strong> agent referrers active in the last 90 days, of those active in the last 365.
                &nbsp;·&nbsp; 🤝 <strong>${win.clients90}/${win.clients365}</strong> client referrers.
                ${quiet > 0 ? `<strong>${quiet}</strong> ${quiet === 1 ? 'person has' : 'people have'} referred in the last year but not the last 90 days.` : ''}
            </div>`
            + renderDetailTable(['Referrer', 'Type', 'Active last 90d', 'CPS (365d)', 'Last CPS'],
                win.roster.map(r => [r.name, r.isAgent ? 'Agent' : 'Client', r.recent ? '✅ Yes' : '— No', r.sessions, r.lastDate]),
                'Nobody has referred a CPS in the last 365 days');
    })();

    const sessionsTable = `<h4 style="font-size:14px;font-weight:600;margin:18px 0 8px;">Sessions (${rows.length})</h4>`
        + renderDetailTable(['Date', 'Lead Agent', 'Customer / Prospect', 'Referred By', 'Referrer Type', 'Title'], rows);

    return summary + byReferrerTable + windowSection + sessionsTable;
};

const buildTotalSalesDetails = async (from, to) => {
    const _det = await _tryPurchaseDetails(from, to);
    if (_det) {
        const rows = [];
        let total = 0;
        for (const p of _det) {
            if (p.is_agent_package) continue;
            total += p.amount || 0;
            rows.push([p.date, p.agent_name || '—', p.customer_name || '—', `RM ${(p.amount || 0).toLocaleString()}`, p.payment_method || '—', p.item || '—']);
        }
        const summary = `<div style="background:#ecfdf5;border:1px solid #a7f3d0;border-radius:6px;padding:10px 14px;margin-bottom:12px;font-size:13px;">Total: <strong>RM ${total.toLocaleString()}</strong> across ${rows.length} sale${rows.length===1?'':'s'}</div>`;
        return summary + renderDetailTable(['Date', 'Agent', 'Customer', 'Amount', 'Method', 'Item'], rows);
    }
    // Fallback: whole-table client path.
    const [purchases, users, customers] = await Promise.all([
        AppDataStore.getAll('purchases'),
        AppDataStore.getAll('users'),
        AppDataStore.getAll('customers')
    ]);
    const userMap = {}; users.forEach(u => { userMap[u.id] = u; });
    const custMap = {}; customers.forEach(c => { custMap[c.id] = c; });
    const rows = [];
    let total = 0;
    // Market scope: when a specific market is active, count only that market's
    // currency (parity with _passesPurchaseFilter / the market-scoped card).
    const _ms = window._crmUtils.listCountryScope();
    const _scoped = _ms !== window._crmUtils.ALL_COUNTRIES;
    for (const p of purchases) {
        if (p.date < from || p.date > to || p.is_agent_package) continue;
        if (_scoped && (p.currency || 'MYR') !== UI.currencyForCountry(_ms)) continue;
        // agent-first: frozen sale credit wins over the live owner (see _getPurchaseAgentId)
        const agentId = p.agent_id || custMap[p.customer_id]?.responsible_agent_id;
        if (_visibleUserIds !== 'all' && !_visibleUserIds.map(String).includes(String(agentId))) continue;
        if (_currentRoleFilter !== 'All') {
            const agent = userMap[agentId] || userMap[String(agentId)];
            if (!agent || agent.role !== _currentRoleFilter) continue;
        }
        const agentName = userMap[agentId]?.full_name || userMap[String(agentId)]?.full_name || '—';
        const custName = custMap[p.customer_id]?.full_name || '—';
        total += p.amount || 0;
        rows.push([p.date, agentName, custName, `RM ${(p.amount || 0).toLocaleString()}`, p.payment_method || '—', p.item || '—']);
    }
    const summary = `<div style="background:#ecfdf5;border:1px solid #a7f3d0;border-radius:6px;padding:10px 14px;margin-bottom:12px;font-size:13px;">Total: <strong>RM ${total.toLocaleString()}</strong> across ${rows.length} sale${rows.length===1?'':'s'}</div>`;
    return summary + renderDetailTable(['Date', 'Agent', 'Customer', 'Amount', 'Method', 'Item'], rows);
};

